const r=(key,label,min,max,step,unit='')=>({key,label,min,max,step,unit});
const s=(key,label,options)=>({key,label,options});
const textbook=(v,page)=>`https://openstax.org/books/university-physics-volume-${v}/pages/${page}`;
const phet=slug=>`https://phet.colorado.edu/en/simulations/${slug}`;
export const PHET_LABS={
 track:{name:'Energy on a track',file:'energy-track.html',group:'mechanics',formula:'K + U + Q = constant',description:'Release a skater into a circular bowl and track kinetic, gravitational, and thermal energy.',heading:'Follow the energy around the bowl.',view:'CIRCULAR BOWL · SIDE VIEW',caption:'Motion in physical seconds · Skater enlarged',badge:'NUMERICAL MODEL',defaults:{mass:60,radius:4,angle:55,drag:0},controls:[r('mass','Skater mass',20,100,5,'kg'),r('radius','Bowl radius',2,6,.25,'m'),r('angle','Release angle from vertical',10,75,1,'°'),r('drag','Tangential drag coefficient',0,10,.5,'N·s/m')],insight:'Gravity trades potential energy for motion. Linear drag converts mechanical energy into thermal energy. With drag set to zero, the skater returns to the same height.',note:'A point skater constrained inside a fixed circular bowl, released from rest. Linear tangential drag F = −bv is a teaching model for energy loss, not dry friction. The bowl supplies the radial contact force. Angles stay below 90° so contact is maintained. RK4 uses 0.005 s steps; thermal energy accumulates from bv². No rolling, jumps, or air-flow solver.',equations:'θ̈ = −(g/R)sin θ − (b/m)θ̇; h = R(1 − cos θ); v = Rθ̇. K = mv²/2, U = mgh, dQ/dt = bv².',source:textbook(1,'8-3-conservation-of-energy'),phet:phet('energy-skate-park'),phetName:'Energy Skate Park',challenge:['Let energy change form','Set drag to 4 N·s/m. Watch each swing shrink while the total energy, including thermal energy, stays constant.',{mass:60,radius:4,angle:55,drag:4}]},
 forces:{name:'Forces & motion',file:'forces-motion.html',group:'mechanics',formula:'ΣF = ma',description:'Apply a horizontal force to a block and compare friction, acceleration, and displacement.',heading:'A net force changes velocity.',view:'HORIZONTAL SURFACE · SIDE VIEW',caption:'Released from rest · 36-second repeating trials',defaults:{mass:20,force:100,mu:.2},controls:[r('mass','Block mass',5,100,5,'kg'),r('force','Applied force (right +)',-200,200,5,'N'),r('mu','Friction coefficient',0,.8,.01)],insight:'Static friction holds the block until the applied force exceeds its limit. Once it slides, a constant net force produces constant acceleration. Negative force sends the block left.',note:'Block released from rest on a horizontal surface under a constant applied force. One coefficient is used for limiting static and kinetic friction. No air resistance; normal force balances weight. Each 8 s physical trial is slowed across 30 s of playback, followed by a 6 s observation pause. The camera follows the block.',equations:'N = mg. If |F| ≤ μmg, static friction cancels F. Otherwise Fnet = F − sign(F)μmg; a = Fnet/m, v = at, x = at²/2.',source:textbook(1,'6-2-friction'),phet:phet('forces-and-motion-basics'),phetName:'Forces and Motion: Basics',challenge:['Find the force needed to move','For 20 kg and μ = 0.3, increase force through 60 N. Check the net force before and after motion starts.',{mass:20,force:55,mu:.3}]},
 balance:{name:'Torque balance',file:'torque-balance.html',group:'mechanics',static:true,formula:'τnet = 0 at balance',description:'Move masses along a beam and find the lever arms that balance their torques.',heading:'Distance matters as much as mass.',view:'HORIZONTAL BEAM · TORQUE DIAGNOSTIC',caption:'Beam held horizontal · No rotational-motion solver',defaults:{m1:10,m2:20,left:1.5,right:.75},controls:[r('m1','Left mass',5,50,5,'kg'),r('left','Left distance from pivot',.25,2,.05,'m'),r('m2','Right mass',5,50,5,'kg'),r('right','Right distance from pivot',.25,2,.05,'m')],insight:'A small mass farther from the pivot can balance a larger mass closer to it. At balance, clockwise and counterclockwise torques cancel.',note:'Massless horizontal beam with two point loads and a frictionless central pivot. The beam is held at zero angle; when torques differ, an external holding torque is needed. The rotation that would follow release is not simulated. Gravity is 9.81 m/s² and positive torque is counterclockwise.',equations:'τleft = mleft g dleft; τright = −mright g dright. Balance requires mleft dleft = mright dright. The pivot supports the combined weight.',source:textbook(1,'12-1-conditions-for-static-equilibrium'),phet:phet('balancing-act'),phetName:'Balancing Act',challenge:['Balance unequal masses','Keep 10 kg at 1.5 m on the left. Find where 30 kg must sit on the right.',{m1:10,m2:30,left:1.5,right:1}]},
 pressure:{name:'Under pressure',file:'under-pressure.html',group:'thermal',static:true,formula:'P = Psurface + ρgh',description:'Lower a pressure probe into a fluid and compare depth, density, gravity, and surface pressure.',heading:'Pressure rises with depth.',view:'STATIC FLUID · SIDE VIEW',caption:'Pressure is isotropic · Probe depth measured below surface',defaults:{density:1000,depth:4,gravity:9.81,atmosphere:101.3},controls:[r('depth','Probe depth',0,10,.1,'m'),r('density','Fluid density',500,1500,50,'kg/m³'),r('gravity','Gravity',1.62,24.79,.01,'m/s²'),r('atmosphere','Surface pressure',0,200,.1,'kPa')],insight:'The fluid above the probe adds pressure. Gauge pressure measures the increase over the surface pressure; absolute pressure includes both.',note:'An incompressible fluid at rest under uniform gravity. The fluid surface is horizontal and its pressure is set by you. The vessel shape does not alter pressure at a given depth. No flowing fluid, compressibility, waves, or bubbles are modeled.',equations:'Pgauge = ρgh; Pabsolute = Psurface + ρgh. At a point, static pressure acts equally in every direction.',source:textbook(1,'14-1-fluids-density-and-pressure'),phet:phet('under-pressure'),phetName:'Under Pressure',challenge:['Double the depth','Record gauge pressure at 3 m, then lower the probe to 6 m. Compare absolute pressure separately.',{density:1000,depth:3,gravity:9.81,atmosphere:101.3}]},
 capacitor:{name:'Capacitor lab',file:'capacitor-lab.html',group:'electricity',static:true,formula:'C = ε₀εᵣA / d',description:'Change plate geometry and dielectric, with either fixed voltage or fixed charge.',heading:'Geometry changes stored energy.',view:'PARALLEL PLATES · FIELD & POTENTIAL',caption:'Fringing neglected · Geometry schematic · Field arrows normalized',defaults:{mode:'connected',area:200,distance:5,dielectric:1,voltage:10,charge:5},controls:[s('mode','Electrical constraint',[['connected','Connected: fixed voltage'],['isolated','Isolated: fixed charge']]),r('area','Plate area',100,500,10,'cm²'),r('distance','Plate separation',1,10,.5,'mm'),r('dielectric','Relative permittivity',1,5,.1),r('voltage','Voltage (connected mode)',-20,20,1,'V'),r('charge','Left charge (isolated mode)',-20,20,.5,'nC')],insight:'At fixed voltage, increasing capacitance draws more charge from the source. At fixed charge, the same change lowers voltage and stored energy. The field points from higher to lower potential.',note:'Ideal parallel plates with a dielectric filling the entire gap. Uniform field and negligible fringing; no leakage or dielectric breakdown. Connected mode maintains the voltage slider; isolated mode maintains the charge slider. Switching modes sets a new experiment rather than simulating a switching transient. Right-plate charge is the negative of the left-plate charge.',equations:'C = ε₀εᵣA/d; Q = CV; U = CV²/2 = Q²/(2C); E = V/d. Potential decreases linearly across the gap along the electric field.',source:textbook(2,'8-1-capacitors-and-capacitance'),phet:phet('capacitor-lab-basics'),phetName:'Capacitor Lab: Basics',challenge:['Hold the charge fixed','Select isolated mode and 5 nC. Increase permittivity from 1 to 3. Compare capacitance, voltage, and energy.',{mode:'isolated',area:200,distance:5,dielectric:1,voltage:10,charge:5}]},
 fields:{name:'Charges & fields',file:'charges-fields.html',group:'electricity',static:true,formula:'E = Σ kq r̂ / r²',description:'Arrange charge signs and move a probe to measure the combined electric field and potential.',heading:'Add fields as vectors.',view:'TWO CHARGES · TOP VIEW',caption:'Arrows show direction only · Probe gives field magnitude',defaults:{q1:2,q2:-2,x:0,y:.5},controls:[r('q1','Left charge',-5,5,.5,'μC'),r('q2','Right charge',-5,5,.5,'μC'),r('x','Probe horizontal position',-1.8,1.8,.05,'m'),r('y','Probe vertical position',-1.2,1.2,.05,'m')],insight:'Fields add as vectors, while potentials add as signed numbers. Between equal opposite charges, the potential can be zero even when the electric field is strong.',note:'Stationary point charges at x = −0.5 m and +0.5 m in vacuum, held by external supports. The probe does not disturb the field. Grid arrows have normalized length, so they show direction only. The numerical field and potential are not softened. Sampling is disabled within 0.06 m of either nonzero charge to avoid the point-charge singularity.',equations:'E(x,y) = Σ kq(x − xq, y − yq)/r³; V = Σ kq/r, with V = 0 at infinity. Positive test charges would accelerate along E.',source:textbook(2,'5-5-calculating-electric-fields'),phet:phet('charges-and-fields'),phetName:'Charges and Fields',challenge:['Zero potential, nonzero field','Place the probe at (0, 0) between +2 μC and −2 μC. Compare the field with the potential.',{q1:2,q2:-2,x:0,y:0}]},
 wire:{name:'Resistance in a wire',file:'wire-resistance.html',group:'electricity',static:true,formula:'R = ρL / A',description:'Compare wire materials, length, thickness, and the current through an ideal voltage source.',heading:'Longer resists. Thicker conducts.',view:'UNIFORM OHMIC WIRE',caption:'Fixed material temperature · Geometry schematic',defaults:{material:'copper',length:5,area:1,voltage:1},controls:[s('material','Wire material',[['copper','Copper'],['aluminium','Aluminium'],['nichrome','Nichrome']]),r('length','Wire length',1,20,.5,'m'),r('area','Cross-sectional area',.1,5,.1,'mm²'),r('voltage','Source voltage',0,2,.1,'V')],insight:'Doubling length doubles resistance. Doubling cross-sectional area halves it. A material with higher resistivity gives less current at the same applied voltage.',note:'Uniform ohmic wire at a fixed temperature of about 20°C, connected to an ideal voltage source. Resistivities are representative values and vary by alloy and purity. Numerical current may be large for low resistance: this model omits heating, source limits, contact resistance, and magnetic effects. Geometry is schematic.',equations:'R = ρL/A; I = V/R; P = VI. Copper ρ = 1.68×10⁻⁸ Ω·m; aluminium 2.82×10⁻⁸; nichrome 1.10×10⁻⁶.',source:textbook(2,'9-3-resistivity-and-resistance'),phet:phet('resistance-in-a-wire'),phetName:'Resistance in a Wire',challenge:['Same size, different material','Compare copper and nichrome with identical length, area, and voltage. Predict which has the greater current.',{material:'copper',length:5,area:1,voltage:1}]},
 blackbody:{name:'Blackbody spectrum',file:'blackbody-spectrum.html',group:'space',static:true,formula:'λpeak T = 2.898 × 10⁻³ m·K',description:'Heat an ideal emitter and inspect the spectrum from ultraviolet through infrared.',heading:'Temperature changes the whole spectrum.',view:'PLANCK SPECTRUM · LOG WAVELENGTH AXIS',caption:'Spectral flux per μm · Plot auto-scales vertically',defaults:{temperature:5800},controls:[r('temperature','Emitter temperature',300,12000,50,'K')],insight:'Hotter objects emit more energy at every wavelength, and their peak shifts toward shorter wavelengths. Doubling temperature multiplies total emitted power per area by sixteen.',note:'Ideal blackbody with emissivity 1. The graph shows hemispherical emitted spectral power per area and per micrometre, not perceived color. Its vertical scale changes with temperature; use the readouts to compare absolute values. Total flux integrates all wavelengths, including those outside the plotted 0.1–30 μm range. No spectral lines or incoming radiation.',equations:'Mλ = 2πhc²/[λ⁵(exp(hc/λkBT) − 1)]; λpeak = 2.897771955×10⁻³/T metres; total emitted flux = σT⁴.',source:textbook(3,'6-1-blackbody-radiation'),phet:phet('blackbody-spectrum'),phetName:'Blackbody Spectrum',challenge:['Heat a Sun-like emitter','Record the spectrum at 5800 K, then double temperature to 11600 K. Check the peak shift and total flux.',{temperature:5800}]},
 kepler:{name:'Kepler orbits',file:'kepler-orbits.html',group:'space',formula:'T² = 4π²a³ / G(M + m)',description:'Explore an eccentric orbit with both bodies moving around their shared barycenter.',heading:'Faster near the star. Slower far away.',view:'TWO-BODY ELLIPSE · BARYCENTER FRAME',caption:'Distances in AU · Bodies enlarged · One orbit per 36 s at 1×',defaults:{star:1,planet:1,axis:1,eccentricity:.35},controls:[r('star','Star mass',.5,3,.1,'M☉'),r('planet','Planet mass',1,1000,1,'M⊕'),r('axis','Relative semimajor axis',.5,5,.1,'AU'),r('eccentricity','Eccentricity',0,.8,.01)],insight:'Both bodies orbit their common center of mass. The line joining them sweeps equal areas in equal times, so their relative speed is greatest at closest approach.',note:'Exact bound Newtonian two-body solution, computed using Kepler’s equation. Star and planet move around the barycenter; the dashed ellipse depicts their relative separation vector from the barycenter for comparison. No other bodies, tidal deformation, relativistic precession, or collisions. G = 4π² in AU, years, and solar masses is an astronomical approximation. The area sector follows the relative vector.',equations:'E − e sin E = nt; r = a(1 − e cos E); n²a³ = G(M + m). Star position = −m/(M+m) rvector; planet position = M/(M+m) rvector. Areal rate = √[G(M+m)a(1−e²)]/2.',source:textbook(1,'13-5-keplers-laws-of-planetary-motion'),phet:phet('keplers-laws'),phetName:"Kepler’s Laws",challenge:['Make the speed vary','Use eccentricity 0.7. Pause near closest and farthest approach, then compare the relative speed readout.',{star:1,planet:1000,axis:1,eccentricity:.7}]},
 fourier:{name:'Fourier wave builder',file:'fourier-waves.html',group:'waves',formula:'y = Σ Aₙ sin(nkx − nωt)',description:'Add harmonics to approximate square, sawtooth, and triangle waveforms.',heading:'Many smooth waves. One new shape.',view:'TRAVELING FOURIER SERIES',caption:'Displacement in cm · Two wavelengths · One cycle per 8 s at 1×',defaults:{shape:'square',terms:5,amplitude:1,frequency:1,length:2},controls:[s('shape','Target waveform',[['square','Square'],['sawtooth','Sawtooth'],['triangle','Triangle']]),r('terms','Terms through harmonic N',1,12,1),r('amplitude','Target amplitude',.5,2,.1,'cm'),r('frequency','Fundamental frequency',.5,3,.1,'Hz'),r('length','Fundamental wavelength',1,4,.25,'m')],insight:'A wave can be built from sinusoidal harmonics. Odd harmonics make square and triangle waves; a sawtooth needs both odd and even terms. More terms sharpen the shape, with overshoot near discontinuities.',note:'A prescribed linear, nondispersive traveling waveform. Harmonic n has frequency nf and wavelength λ/n, so all components share speed fλ. This is waveform synthesis, not a nonlinear medium solver. Terms means all harmonics up to N; some coefficients are zero. Displacement is in centimetres. Playback is slowed independently of physical time.',equations:'Square: Aₙ = 4A/(πn) for odd n. Sawtooth: Aₙ = 2A(−1)ⁿ⁺¹/(πn). Triangle: Aₙ = 8A(−1)⁽ⁿ⁻¹⁾/²/(π²n²) for odd n. Other coefficients are zero.',source:textbook(1,'16-5-interference-of-waves'),phet:phet('fourier-making-waves'),phetName:'Fourier: Making Waves',challenge:['Build a square wave','Compare 1, 5, and 11 terms. Inspect the corners and the overshoot beside each jump.',{shape:'square',terms:1,amplitude:1,frequency:1,length:2}]},
 scattering:{name:'Rutherford scattering',file:'rutherford-scattering.html',group:'space',formula:'tan(|θ|/2) = kQq / (2Eb)',description:'Aim an alpha particle past a positive nucleus and watch its exact Coulomb trajectory.',heading:'A close encounter bends the path.',view:'ALPHA PARTICLE · NUCLEAR SCALE',caption:'Distances in fm · Greatly slowed · 40-second repeating trials',defaults:{protons:79,energy:5,impact:80},controls:[r('protons','Nuclear proton count',20,79,1),r('energy','Incoming alpha energy',2,10,.1,'MeV'),r('impact','Signed impact parameter',-200,200,5,'fm')],insight:'A closer encounter bends an alpha particle more strongly. A head-on particle turns back, while a higher-energy particle gets closer before repulsion reverses its radial motion.',note:'Exact nonrelativistic repulsive Coulomb hyperbola for an alpha particle (+2e) scattering from a fixed, infinitely massive point nucleus. Incoming energy and impact parameter refer to the asymptotic trajectory. The finite displayed path starts and ends far from the nucleus; kinetic energy there is below the asymptotic energy. Nuclear recoil, electron screening, strong interactions, and quantum effects are omitted. One traversal takes 34 s of playback, followed by 6 s to inspect the outcome.',equations:'α = k(2e)(Ze); a = α/(2E); eccentricity = √(1 + (b/a)²). rmin = a(1 + eccentricity); |θ| = 2 atan(a/|b|). K(r) + α/r = E.',source:'https://openstax.org/books/college-physics-2e/pages/30-2-discovery-of-the-parts-of-the-atom-electrons-and-nuclei',sourceLabel:'Read about Rutherford’s experiment in OpenStax',phet:phet('rutherford-scattering'),phetName:'Rutherford Scattering',challenge:['Try a head-on encounter','Set impact parameter to zero. Watch the particle slow down, turn around, and return along its incoming line.',{protons:79,energy:5,impact:0}]},
 atom:{name:'Build an atom',file:'build-atom.html',group:'space',static:true,formula:'A = Z + N · charge = Z − electrons',description:'Choose protons, neutrons, and electrons to identify an element, isotope, and ion.',heading:'Protons choose the element.',view:'PARTICLE COUNTS · SHELL DIAGRAM',caption:'Schematic electron shells · Not classical orbits or nuclear structure',defaults:{protons:6,neutrons:6,electrons:6},controls:[r('protons','Protons',1,10,1),r('neutrons','Neutrons',0,16,1),r('electrons','Electrons',0,12,1)],insight:'Changing protons changes the element. Changing neutrons changes the isotope. Changing electrons changes the charge while leaving the element and mass number unchanged.',note:'A counting model for the first ten elements, not a nuclear or quantum dynamics simulation. Electron shell counts use a simplified 2, 8, then outer-shell arrangement. Dots show counts rather than electron trajectories. Particle choices can include unstable nuclei or unbound ions; this model does not predict stability, binding, decay, or electron configurations for every charged state.',equations:'Atomic number Z = proton count. Mass number A = protons + neutrons. Net charge in units of e = protons − electrons.',source:textbook(3,'8-1-the-hydrogen-atom'),phet:phet('build-an-atom'),phetName:'Build an Atom',challenge:['Make a carbon ion','Keep 6 protons and 6 neutrons. Remove two electrons, then add one neutron. Which labels change each time?',{protons:6,neutrons:6,electrons:4}]}
};
